    private final class Toggle extends FrameLayout {boolean checked;final TextView title,caption;final DiaryMotion thumb;final Consumer<Boolean> commit;Toggle(String title,String caption,boolean checked,Consumer<Boolean> commit){super(context,null,0,0);this.checked=checked;this.commit=commit;setWillNotDraw(false);setMinimumHeight(dp(65));this.title=text(title,13,INK,true);this.caption=text(caption,10,MUTED,false);this.caption.setMaxLines(2);FrameLayout.LayoutParams t=new FrameLayout.LayoutParams(-1,dp(25));t.rightMargin=dp(65);addView(this.title,t);FrameLayout.LayoutParams b=new FrameLayout.LayoutParams(-1,dp(34));b.topMargin=dp(27);b.rightMargin=dp(60);addView(this.caption,b);thumb=motion(this,checked?1:0,v->invalidate());setClickable(true);setFocusable(true);setContentDescription(title+(checked?"，已开启":"，已关闭"));setOnClickListener(v->{this.checked=!this.checked;thumb.to(this.checked?1:0);setContentDescription(title+(this.checked?"，已开启":"，已关闭"));commit.accept(this.checked);performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);});}protected void onDraw(Canvas c){Paint p=new Paint(3);float x=getWidth()-dp(48),y=dp(7);p.setColor(checked?0xffac8eae:0xff514252);c.drawRoundRect(x,y,x+dp(47),y+dp(29),dp(18),dp(18),p);p.setColor(0xfff7eaf8);c.drawCircle(x+dp(15)+dp(17)*thumb.value,y+dp(14.5f),dp(11),p);}public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setClassName("android.widget.Switch");info.setCheckable(true);info.setChecked(checked);}}
    private final class Rhythm extends View {final long[] hours=new long[24];final Paint p=new Paint(3);Rhythm(JSONArray spans){super(context,null,0,0);for(int i=0;i<spans.length();i++){JSONObject s=spans.optJSONObject(i);if(s==null)continue;long start=s.optLong("start"),end=s.optLong("end");Calendar cal=Calendar.getInstance(TimeZone.getTimeZone(s.optString("zone",data.optString("zone"))));while(start<end){long next=Math.min(end,(Math.floorDiv(start,3600000)+1)*3600000);cal.setTimeInMillis(start);hours[cal.get(Calendar.HOUR_OF_DAY)]+=next-start;start=next;}}setContentDescription("24 小时听歌分布");}protected void onDraw(Canvas c){p.setColor(0x9c231b2a);c.drawRoundRect(0,0,getWidth(),getHeight(),dp(22),dp(22),p);long max=60000;for(long v:hours)max=Math.max(max,v);float bw=(getWidth()-dp(30)-dp(3)*23)/24f,bottom=getHeight()-dp(27);for(int i=0;i<24;i++){float h=Math.max(dp(3),hours[i]/(float)max*dp(78));p.setShader(new LinearGradient(0,bottom-h,0,bottom,0xffefd2df,0xff765e86,Shader.TileMode.CLAMP));c.drawRoundRect(dp(15)+i*(bw+dp(3)),bottom-h,dp(15)+i*(bw+dp(3))+bw,bottom,dp(3),dp(3),p);}p.setShader(null);p.setColor(MUTED);p.setTextSize(dp(8));for(int i=0;i<=4;i++){p.setTextAlign(i==4?Paint.Align.RIGHT:Paint.Align.LEFT);c.drawText(String.format(Locale.ROOT,"%02d:00",i*6),dp(15)+(getWidth()-dp(30))*i/4,getHeight()-dp(10),p);}}}
